var i=`0151-qutab`;var t=`world-0151`;var o=`AZ`;var a=`western-asia`;var l=4;var s=75;var r={en:`Qutab`,ua:`Кутаб`};var g={en:`A classic dish from Azerbaijan, featuring ground lamb, yellow onion, parsley. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Азербайджан. Основні складники: фарш з ягнятини, жовта цибуля, петрушка. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 30 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 30 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:30,i:[[`all-purpose-flour`,450,`g`],[`water`,225,`ml`],[`table-salt`,5,`g`],[`sunflower-oil`,25,`ml`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:10,i:[[`ground-lamb`,340,`g`],[`yellow-onion`,130,`g`],[`parsley`,25,`g`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Roll the dough into thin rounds; spread the raw lamb filling on half of each round and fold into a semicircle, pressing the edges firmly.`,ua:`Розкачайте тісто на тонкі кружальця; розподіліть сиру начинку з баранини на половині кожного, складіть півмісяцем і щільно притисніть краї.`,t:[`pressing`,`rolling-out-dough`],m:20,i:[]},{en:`Cook the qutabs on a lightly buttered griddle or skillet, turning until both sides are speckled brown and the lamb filling is fully cooked.`,ua:`Смажте кутаби на злегка змащеній маслом сухій сковороді, перевертаючи до рум’яних плям з обох боків і повної готовності баранини.`,t:[`pan-frying`],m:12,i:[[`unsalted-butter`,45,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`sumac`,10,`g`]]}];var d={slug:i,id:t,country:`AZ`,region:a,servings:4,minutes:75,title:r,text:g,steps:u};export{o as country,d as default,t as id,s as minutes,a as region,l as servings,i as slug,u as steps,g as text,r as title};